    out, cur = [], ''
    i, n = 0, len(line)
    while i < n:
        ch = line[i]
        if ch.isspace():
            if cur:
                out.append(cur)
                cur = ''
            i += 1
        elif ch == "'":
            j = i + 1
            while j < n and line[j] != "'":
                cur += line[j]
                j += 1
            if j >= n:
                raise ValueError("unterminated single quote")
            i = j + 1
        elif ch == '"':
            i += 1
            while i < n and line[i] != '"':
                c = line[i]
                if c == '\\' and i + 1 < n and line[i + 1] in ('"', '\\'):
                    cur += line[i + 1]
                    i += 2
                else:
                    cur += c
                    i += 1
            if i >= n:
                raise ValueError("unterminated double quote")
            i += 1
        elif ch == '\\':
            if i + 1 < n:
                cur += line[i + 1]
                i += 2
            else:
                cur += ch
                i += 1
        else:
            cur += ch
            i += 1
    if cur:
        out.append(cur)
    return out

